/* Orchard — Premium Tech E-Commerce Store Styles */

/* ============================================
   CSS Custom Properties (Design Tokens)
   ============================================ */
:root {
  /* Colors */
  --color-bg: #ffffff;
  --color-bg-secondary: #f5f5f7;
  --color-text: #1d1d1f;
  --color-text-secondary: #6e6e73;
  --color-link: #0066cc;
  --color-link-hover: #0077ed;
  --color-border: #d2d2d7;
  --color-border-light: #e8e8ed;

  /* Typography */
  --font-sans: -apple-system, BlinkMacSystemFont, "SF Pro Text", "SF Pro Display", "Helvetica Neue", "Inter", system-ui, sans-serif;
  --font-mono: "SF Mono", "JetBrains Mono", ui-monospace, monospace;

  /* Spacing Scale */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  /* Shadows */
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.12);

  /* Radius */
  --radius-sm: 0.5rem;
  --radius-md: 0.75rem;
  --radius-lg: 1rem;
  --radius-xl: 1.25rem;
  --radius-full: 9999px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
}

/* ============================================
   Base Reset & Typography
   ============================================ */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background: var(--color-bg);
  line-height: 1.5;
  font-size: 16px;
}

a {
  color: var(--color-link);
  text-decoration: none;
  transition: color var(--transition-fast);
}
a:hover {
  color: var(--color-link-hover);
  text-decoration: underline;
}

img {
  max-width: 100%;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* ============================================
   Utility Classes
   ============================================ */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--space-6);
}

.text-center { text-align: center; }
.text-secondary { color: var(--color-text-secondary); }

/* ============================================
   Header / Navigation
   ============================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255,255,255,0.82);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border-light);
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 52px;
}

.logo {
  font-size: 1.25rem;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--color-text);
}
.logo:hover { text-decoration: none; color: var(--color-text); }

.nav-links {
  display: flex;
  gap: var(--space-6);
}
.nav-links a {
  font-size: 0.875rem;
  color: var(--color-text);
  opacity: 0.85;
  transition: opacity var(--transition-fast);
}
.nav-links a:hover {
  opacity: 1;
  text-decoration: none;
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: var(--space-4);
}

.mobile-menu-btn {
  display: none;
  padding: var(--space-2);
}

/* ============================================
   Ribbon Banner
   ============================================ */
.ribbon {
  background: var(--color-bg-secondary);
  text-align: center;
  padding: var(--space-3) var(--space-4);
  font-size: 0.8125rem;
  color: var(--color-text);
}
.ribbon a {
  color: var(--color-link);
}

/* ============================================
   Hero Section
   ============================================ */
.hero {
  padding: var(--space-20) var(--space-6);
  text-align: center;
  background: var(--color-bg);
}
.hero-title {
  font-size: clamp(2.5rem, 5vw, 3.5rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  line-height: 1.1;
  margin-bottom: var(--space-4);
}
.hero-subtitle {
  font-size: clamp(1.125rem, 2vw, 1.375rem);
  color: var(--color-text-secondary);
  font-weight: 400;
  margin-bottom: var(--space-6);
}
.hero-ctas {
  display: flex;
  gap: var(--space-6);
  justify-content: center;
  flex-wrap: wrap;
}

/* ============================================
   Buttons
   ============================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-5);
  border-radius: var(--radius-full);
  font-size: 0.9375rem;
  font-weight: 500;
  transition: all var(--transition-fast);
  white-space: nowrap;
}
.btn-primary {
  background: var(--color-link);
  color: #fff;
}
.btn-primary:hover {
  background: var(--color-link-hover);
  text-decoration: none;
  color: #fff;
}
.btn-secondary {
  background: transparent;
  color: var(--color-link);
  border: 1px solid var(--color-link);
}
.btn-secondary:hover {
  background: var(--color-link);
  color: #fff;
  text-decoration: none;
}
.btn-ghost {
  color: var(--color-link);
  padding: var(--space-2) 0;
}
.btn-ghost:hover {
  text-decoration: underline;
}

/* ============================================
   Product Grid (Homepage Showcase)
   ============================================ */
.product-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-4);
  padding: var(--space-4);
  max-width: 1400px;
  margin: 0 auto;
}

.product-tile {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--color-bg-secondary);
  min-height: 520px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  padding: var(--space-12) var(--space-8) var(--space-8);
  text-align: center;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}
.product-tile:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}
.product-tile.dark {
  background: #1d1d1f;
  color: #fff;
}
.product-tile.dark .tile-tagline {
  color: rgba(255,255,255,0.75);
}
.product-tile.dark .btn-secondary {
  border-color: #fff;
  color: #fff;
}
.product-tile.dark .btn-secondary:hover {
  background: #fff;
  color: #1d1d1f;
}

.tile-title {
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: var(--space-2);
}
.tile-tagline {
  font-size: 1.0625rem;
  color: var(--color-text-secondary);
  margin-bottom: var(--space-4);
  max-width: 360px;
}
.tile-ctas {
  display: flex;
  gap: var(--space-6);
  margin-bottom: var(--space-8);
}
.tile-img {
  width: 100%;
  max-width: 380px;
  height: auto;
  object-fit: contain;
  margin-top: auto;
}

/* ============================================
   Section Headers
   ============================================ */
.section-header {
  text-align: center;
  padding: var(--space-16) var(--space-6) var(--space-8);
}
.section-title {
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: var(--space-2);
}
.section-subtitle {
  font-size: 1.0625rem;
  color: var(--color-text-secondary);
}

/* ============================================
   Carousel Component
   ============================================ */
.carousel-wrap {
  position: relative;
  padding: 0 var(--space-6);
  max-width: 1400px;
  margin: 0 auto var(--space-16);
}
.carousel {
  display: flex;
  gap: var(--space-4);
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  padding: var(--space-4) 0;
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.carousel::-webkit-scrollbar { display: none; }

.carousel-card {
  flex: 0 0 auto;
  scroll-snap-align: start;
  background: var(--color-bg-secondary);
  border-radius: var(--radius-lg);
  overflow: hidden;
  width: 320px;
  display: flex;
  flex-direction: column;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}
.carousel-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}
.carousel-card.wide {
  width: 400px;
}
.carousel-card .card-img {
  width: 100%;
  height: 220px;
  object-fit: cover;
  background: linear-gradient(135deg, #e8e8ed 0%, #d2d2d7 100%);
}
.carousel-card .card-body {
  padding: var(--space-5);
  flex: 1;
  display: flex;
  flex-direction: column;
}
.carousel-card .card-badge {
  display: inline-block;
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #c2410c;
  margin-bottom: var(--space-2);
}
.carousel-card .card-title {
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: var(--space-1);
}
.carousel-card .card-desc {
  font-size: 0.875rem;
  color: var(--color-text-secondary);
  margin-bottom: var(--space-3);
  flex: 1;
}
.carousel-card .card-price {
  font-size: 0.9375rem;
  font-weight: 500;
  margin-bottom: var(--space-1);
}
.carousel-card .card-monthly {
  font-size: 0.8125rem;
  color: var(--color-text-secondary);
  margin-bottom: var(--space-3);
}
.carousel-card .card-ctas {
  display: flex;
  gap: var(--space-4);
}

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: rgba(255,255,255,0.9);
  box-shadow: var(--shadow-md);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: background var(--transition-fast), transform var(--transition-fast);
}
.carousel-arrow:hover {
  background: #fff;
  transform: translateY(-50%) scale(1.08);
}
.carousel-arrow.prev { left: 0; }
.carousel-arrow.next { right: 0; }
.carousel-arrow.hidden { display: none; }

/* ============================================
   Icon Bar (Product Categories)
   ============================================ */
.icon-bar {
  display: flex;
  gap: var(--space-8);
  overflow-x: auto;
  padding: var(--space-8) var(--space-6);
  justify-content: center;
  scrollbar-width: none;
}
.icon-bar::-webkit-scrollbar { display: none; }
.icon-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-2);
  min-width: 72px;
  text-align: center;
  color: var(--color-text);
  font-size: 0.8125rem;
  transition: opacity var(--transition-fast);
}
.icon-item:hover {
  opacity: 0.75;
  text-decoration: none;
  color: var(--color-text);
}
.icon-item .icon-box {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  background: var(--color-bg-secondary);
  display: flex;
  align-items: center;
  justify-content: center;
}

/* ============================================
   Entertainment Tabs
   ============================================ */
.tab-bar {
  display: flex;
  gap: var(--space-6);
  justify-content: center;
  margin-bottom: var(--space-8);
  border-bottom: 1px solid var(--color-border-light);
  padding-bottom: var(--space-4);
}
.tab-btn {
  font-size: 1rem;
  font-weight: 500;
  color: var(--color-text-secondary);
  padding: var(--space-2) 0;
  position: relative;
  transition: color var(--transition-fast);
}
.tab-btn:hover { color: var(--color-text); }
.tab-btn.active {
  color: var(--color-text);
}
.tab-btn.active::after {
  content: '';
  position: absolute;
  bottom: -17px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--color-text);
}

.tab-panel {
  display: none;
}
.tab-panel.active {
  display: block;
  animation: fadeIn 350ms ease-out;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ============================================
   Help / Store Difference Cards
   ============================================ */
.info-card {
  flex: 0 0 300px;
  background: var(--color-bg-secondary);
  border-radius: var(--radius-lg);
  padding: var(--space-8) var(--space-6);
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  min-height: 240px;
}
.info-card .info-icon {
  width: 40px;
  height: 40px;
  color: var(--color-link);
}
.info-card .info-title {
  font-size: 1.0625rem;
  font-weight: 600;
}
.info-card .info-desc {
  font-size: 0.875rem;
  color: var(--color-text-secondary);
  flex: 1;
}
.info-card .info-link {
  font-size: 0.9375rem;
  color: var(--color-link);
}

/* ============================================
   Quick Links
   ============================================ */
.quick-links {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-4);
  justify-content: center;
  padding: var(--space-12) var(--space-6);
}
.quick-link {
  padding: var(--space-3) var(--space-5);
  border-radius: var(--radius-full);
  background: var(--color-bg-secondary);
  font-size: 0.9375rem;
  color: var(--color-text);
  transition: background var(--transition-fast);
}
.quick-link:hover {
  background: var(--color-border-light);
  text-decoration: none;
  color: var(--color-text);
}

/* ============================================
   Category Hero
   ============================================ */
.category-hero {
  text-align: center;
  padding: var(--space-20) var(--space-6) var(--space-12);
  background: var(--color-bg);
}
.category-hero h1 {
  font-size: clamp(2.5rem, 5vw, 3.5rem);
  font-weight: 700;
  letter-spacing: -0.03em;
  margin-bottom: var(--space-4);
}
.category-hero p {
  font-size: 1.25rem;
  color: var(--color-text-secondary);
}

/* ============================================
   Sticky Section Nav
   ============================================ */
.section-nav {
  position: sticky;
  top: 52px;
  z-index: 90;
  background: rgba(255,255,255,0.9);
  backdrop-filter: saturate(180%) blur(16px);
  -webkit-backdrop-filter: saturate(180%) blur(16px);
  border-bottom: 1px solid var(--color-border-light);
}
.section-nav-inner {
  display: flex;
  gap: var(--space-6);
  overflow-x: auto;
  padding: var(--space-3) var(--space-6);
  scrollbar-width: none;
  justify-content: center;
}
.section-nav-inner::-webkit-scrollbar { display: none; }
.section-nav a {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text);
  opacity: 0.7;
  white-space: nowrap;
  padding: var(--space-1) 0;
  transition: opacity var(--transition-fast);
}
.section-nav a:hover,
.section-nav a.active {
  opacity: 1;
  text-decoration: none;
}

/* ============================================
   Shopping Guides / Ways to Save
   ============================================ */
.guide-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: var(--space-4);
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 var(--space-6) var(--space-16);
}
.guide-card {
  background: var(--color-bg-secondary);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}
.guide-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}
.guide-card h3 {
  font-size: 1.0625rem;
  font-weight: 600;
  margin-bottom: var(--space-1);
}
.guide-card p {
  font-size: 0.875rem;
  color: var(--color-text-secondary);
}

/* ============================================
   Savings Cards
   ============================================ */
.savings-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: var(--space-4);
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 var(--space-6) var(--space-16);
}
.savings-card {
  background: var(--color-bg-secondary);
  border-radius: var(--radius-lg);
  padding: var(--space-6);
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}
.savings-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-md);
}
.savings-card h3 {
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-1);
}
.savings-card p {
  font-size: 0.875rem;
  color: var(--color-text-secondary);
}

/* ============================================
   Footer
   ============================================ */
.site-footer {
  background: var(--color-bg-secondary);
  padding: var(--space-12) var(--space-6) var(--space-8);
  font-size: 0.8125rem;
  color: var(--color-text-secondary);
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: var(--space-8);
  max-width: 1100px;
  margin: 0 auto var(--space-10);
}
.footer-col h4 {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--color-text);
  margin-bottom: var(--space-3);
}
.footer-col ul li {
  margin-bottom: var(--space-2);
}
.footer-col a {
  color: var(--color-text-secondary);
  transition: color var(--transition-fast);
}
.footer-col a:hover {
  color: var(--color-text);
  text-decoration: underline;
}

.footer-legal {
  max-width: 1100px;
  margin: 0 auto;
  padding-top: var(--space-6);
  border-top: 1px solid var(--color-border-light);
  font-size: 0.75rem;
  line-height: 1.6;
}

/* Mobile accordion */
.footer-col .accordion-toggle {
  display: none;
  width: 100%;
  justify-content: space-between;
  align-items: center;
  padding: var(--space-3) 0;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text);
  border-bottom: 1px solid var(--color-border-light);
}
.footer-col .accordion-toggle i {
  transition: transform var(--transition-fast);
}
.footer-col.open .accordion-toggle i {
  transform: rotate(180deg);
}
.footer-col .accordion-body {
  overflow: hidden;
  transition: max-height 300ms ease;
}

/* ============================================
   Brand Collab Section
   ============================================ */
.brand-collab {
  background: linear-gradient(135deg, #1d1d1f 0%, #2d2d30 100%);
  color: #fff;
  text-align: center;
  padding: var(--space-20) var(--space-6);
  margin-bottom: var(--space-16);
}
.brand-collab h2 {
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: var(--space-3);
}
.brand-collab p {
  font-size: 1.0625rem;
  color: rgba(255,255,255,0.75);
  max-width: 560px;
  margin: 0 auto;
}

/* ============================================
   Responsive Breakpoints
   ============================================ */
@media (max-width: 1024px) {
  .product-grid {
    grid-template-columns: 1fr;
  }
  .product-tile {
    min-height: 460px;
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }
  .mobile-menu-btn {
    display: flex;
  }
  .hero {
    padding: var(--space-12) var(--space-4);
  }
  .carousel-card {
    width: 280px;
  }
  .carousel-card.wide {
    width: 320px;
  }
  .icon-bar {
    justify-content: flex-start;
    gap: var(--space-5);
  }
  .section-nav-inner {
    justify-content: flex-start;
  }

  /* Footer accordion on mobile */
  .footer-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .footer-col .accordion-toggle {
    display: flex;
  }
  .footer-col h4 {
    display: none;
  }
  .footer-col .accordion-body {
    max-height: 0;
  }
  .footer-col.open .accordion-body {
    max-height: 400px;
    padding-bottom: var(--space-4);
  }
  .footer-col ul li {
    margin-bottom: var(--space-3);
  }
}

@media (min-width: 769px) {
  .footer-col .accordion-body {
    max-height: none !important;
  }
}

/* ============================================
   Accessibility
   ============================================ */
:focus-visible {
  outline: 2px solid var(--color-link);
  outline-offset: 2px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/**
 * Orchard — Main JavaScript
 * Handles carousels, tabs, mobile footer accordion, section nav
 */

(function () {
  'use strict';

  /* ============================================
     Carousel Logic
     ============================================ */
  function initCarousels() {
    document.querySelectorAll('.carousel-wrap').forEach(function (wrap) {
      var carousel = wrap.querySelector('.carousel');
      var prevBtn = wrap.querySelector('.carousel-arrow.prev');
      var nextBtn = wrap.querySelector('.carousel-arrow.next');
      if (!carousel) return;

      var scrollAmount = 340; // default card width + gap
      var firstCard = carousel.querySelector('.carousel-card, .info-card');
      if (firstCard) {
        scrollAmount = firstCard.offsetWidth + 16;
      }

      function updateArrows() {
        if (prevBtn) {
          prevBtn.classList.toggle('hidden', carousel.scrollLeft <= 1);
        }
        if (nextBtn) {
          var maxScroll = carousel.scrollWidth - carousel.clientWidth;
          nextBtn.classList.toggle('hidden', carousel.scrollLeft >= maxScroll - 1);
        }
      }

      if (prevBtn) {
        prevBtn.addEventListener('click', function () {
          carousel.scrollBy({ left: -scrollAmount, behavior: 'smooth' });
        });
      }
      if (nextBtn) {
        nextBtn.addEventListener('click', function () {
          carousel.scrollBy({ left: scrollAmount, behavior: 'smooth' });
        });
      }

      carousel.addEventListener('scroll', updateArrows, { passive: true });
      // Initial state
      window.addEventListener('load', updateArrows);
      updateArrows();
    });
  }

  /* ============================================
     Entertainment Tabs
     ============================================ */
  function initTabs() {
    document.querySelectorAll('.tab-bar').forEach(function (bar) {
      var buttons = bar.querySelectorAll('.tab-btn');
      var panels = bar.parentElement.querySelectorAll('.tab-panel');

      buttons.forEach(function (btn) {
        btn.addEventListener('click', function () {
          var target = btn.dataset.tab;

          buttons.forEach(function (b) { b.classList.remove('active'); });
          btn.classList.add('active');

          panels.forEach(function (p) {
            p.classList.toggle('active', p.dataset.panel === target);
          });
        });
      });
    });
  }

  /* ============================================
     Mobile Footer Accordion
     ============================================ */
  function initFooterAccordion() {
    var isMobile = window.matchMedia('(max-width: 768px)').matches;
    if (!isMobile) return;

    document.querySelectorAll('.footer-col').forEach(function (col) {
      var toggle = col.querySelector('.accordion-toggle');
      if (!toggle) return;

      toggle.addEventListener('click', function () {
        col.classList.toggle('open');
      });
    });
  }

  /* ============================================
     Section Nav Active State (scroll spy)
     ============================================ */
  function initScrollSpy() {
    var nav = document.querySelector('.section-nav');
    if (!nav) return;

    var links = nav.querySelectorAll('a[href^="#"]');
    var sections = [];
    links.forEach(function (link) {
      var id = link.getAttribute('href').slice(1);
      var section = document.getElementById(id);
      if (section) sections.push({ link: link, section: section });
    });

    function onScroll() {
      var scrollPos = window.scrollY + 120;
      sections.forEach(function (item) {
        var top = item.section.offsetTop;
        var bottom = top + item.section.offsetHeight;
        if (scrollPos >= top && scrollPos < bottom) {
          sections.forEach(function (s) { s.link.classList.remove('active'); });
          item.link.classList.add('active');
        }
      });
    }

    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();
  }

  /* ============================================
     Mobile Menu Toggle
     ============================================ */
  function initMobileMenu() {
    var btn = document.querySelector('.mobile-menu-btn');
    var menu = document.querySelector('.nav-links');
    if (!btn || !menu) return;

    btn.addEventListener('click', function () {
      var expanded = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', !expanded);
      menu.classList.toggle('mobile-open');
    });
  }

  /* ============================================
     Initialize everything on DOM ready
     ============================================ */
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () {
      initCarousels();
      initTabs();
      initFooterAccordion();
      initScrollSpy();
      initMobileMenu();
      if (window.lucide) lucide.createIcons();
    });
  } else {
    initCarousels();
    initTabs();
    initFooterAccordion();
    initScrollSpy();
    initMobileMenu();
    if (window.lucide) lucide.createIcons();
  }
})();

